cd "$INPUT_DIR" && python3 -c "
import glob,zipfile,re
for f in glob.glob('*.pptx')+glob.glob('*.xlsx'):
    z=zipfile.ZipFile(f)
    txt=' '.join(z.read(n).decode('utf8','ignore') for n in z.namelist() if n.endswith(('.xml','.rels')))
    txt=re.sub('<[^>]+>',' ',txt)
    for kw in ['customer','Customer','client','Client','account name','top 10','concentration','NHS']:
        if kw in txt:
            idxs=[m.start() for m in re.finditer(kw,txt)][:3]
            for i in idxs: print(f,'|',kw,'|',txt[max(0,i-90):i+90].replace('\n',' ')[:190])
" 2>/dev/null | head -40
